#include <FastLED.h>
#include <esp_system.h>

// ========================================
// Hardware und LED-Konfiguration
// ========================================

#define BASE_PIN       6
#define FLOWER_PIN     7

#define BASE_COUNT     24
#define FLOWER_COUNT   6

#define LED_TYPE       WS2812B
#define COLOR_ORDER    GRB

// Softwareseitiges Stromlimit in mA.
// Keine Garantie für die Belastbarkeit des Board-5V-Pfads.
#define MAX_CURRENT_MA 500

CRGB base[BASE_COUNT];
CRGB flowers[FLOWER_COUNT];

// Farben
const CRGB BASE_COLOR   = CRGB(255, 18, 75);
const CRGB FLOWER_COLOR = CRGB(255, 255, 255);

// ========================================
// Animation
// ========================================

struct Pixel {
  uint8_t brightness;
  uint8_t target;
  uint8_t pauseCount;
  int8_t phase; // 0=wartet, 1=Fade-in, 2=Pause, 3=Fade-out
  uint32_t nextTime;
};

Pixel baseState[BASE_COUNT];
Pixel flowerState[FLOWER_COUNT];

uint32_t nextBaseSpawn = 0;
uint32_t nextFlowerSpawn = 0;

// ========================================
// Pixel starten und animieren
// ========================================

void startPixel(Pixel &p) {
  p.brightness = 0;
  p.target = random(100, 256);
  p.phase = 1;
  p.nextTime = millis();
}

void updatePixel(Pixel &p) {
  uint32_t now = millis();

  switch (p.phase) {
    case 0: // Warten
      if (now >= p.nextTime && random(100) < 8) {
        startPixel(p);
      }
      break;

    case 1: // Fade-in
      if (p.brightness < p.target) {
        p.brightness =
          (uint16_t)p.brightness + 3 >= p.target
          ? p.target
          : p.brightness + 3;
      } else {
        p.phase = 2;
        p.nextTime = now + random(250, 1000);
      }
      break;

    case 2: // Kurze Leuchtpause
      if (now >= p.nextTime) {
        p.phase = 3;
      }
      break;

    case 3: // Fade-out
      if (p.brightness > 3) {
        p.brightness -= 3;
      } else {
        p.brightness = 0;
        p.phase = 0;
        p.nextTime = now + random(100, 1200);
      }
      break;
  }
}

void spawnRandom(Pixel states[], int count) {
  // Einige Versuche, einen inaktiven Pixel zu finden
  for (int attempt = 0; attempt < count; attempt++) {
    int i = random(count);

    if (states[i].phase == 0) {
      startPixel(states[i]);
      return;
    }
  }
}

// ========================================
// LED-Ausgabe und Strombegrenzung
// ========================================

// Näherung: maximal ca. 60 mA pro WS2812B
// bei vollem Weiß. Der reale Strom hängt von
// Farbe, LED-Charge und Versorgung ab.
//
// Blumen erhalten Vorrang. Reicht das Limit
// nicht für sie, werden auch sie reduziert.

void renderWithLimit() {
  uint32_t flowerEstimate = 0;
  uint32_t baseEstimate = 0;

  for (int i = 0; i < FLOWER_COUNT; i++) {
    uint32_t channelSum =
      (uint32_t)FLOWER_COLOR.r +
      FLOWER_COLOR.g +
      FLOWER_COLOR.b;

    flowerEstimate +=
      (channelSum * flowerState[i].brightness * 20UL)
      / (255UL * 255UL);
  }

  for (int i = 0; i < BASE_COUNT; i++) {
    uint32_t channelSum =
      (uint32_t)BASE_COLOR.r +
      BASE_COLOR.g +
      BASE_COLOR.b;

    baseEstimate +=
      (channelSum * baseState[i].brightness * 20UL)
      / (255UL * 255UL);
  }

  float flowerScale = 1.0f;
  float baseScale = 1.0f;

  if (flowerEstimate >= MAX_CURRENT_MA) {
    flowerScale =
      (float)MAX_CURRENT_MA /
      (float)max((uint32_t)1, flowerEstimate);

    baseScale = 0;
  } else {
    uint32_t remaining = MAX_CURRENT_MA - flowerEstimate;

    if (baseEstimate > remaining && baseEstimate > 0) {
      baseScale = (float)remaining / baseEstimate;
    }
  }

  // Base darstellen
  for (int i = 0; i < BASE_COUNT; i++) {
    base[i] = BASE_COLOR;
    base[i].nscale8(baseState[i].brightness);
    base[i].nscale8((uint8_t)(baseScale * 255));
  }

  // Blumen darstellen
  for (int i = 0; i < FLOWER_COUNT; i++) {
    flowers[i] = FLOWER_COLOR;
    flowers[i].nscale8(flowerState[i].brightness);
    flowers[i].nscale8((uint8_t)(flowerScale * 255));
  }

  FastLED.show();
}

// ========================================
// Setup
// ========================================

void setup() {
  delay(300);
  randomSeed(esp_random());

  FastLED.addLeds<LED_TYPE, BASE_PIN, COLOR_ORDER>(
    base, BASE_COUNT
  );

  FastLED.addLeds<LED_TYPE, FLOWER_PIN, COLOR_ORDER>(
    flowers, FLOWER_COUNT
  );

  FastLED.setBrightness(255);
  FastLED.clear(true);

  for (auto &p : baseState) {
    p = {0, 0, 0, 0, 0};
  }

  for (auto &p : flowerState) {
    p = {0, 0, 0, 0, 0};
  }

  // Sofort mit zufälligen LEDs beginnen
  for (int i = 0; i < 5; i++) {
    spawnRandom(baseState, BASE_COUNT);
    spawnRandom(flowerState, FLOWER_COUNT);
  }

  nextBaseSpawn = millis() + 200;
  nextFlowerSpawn = millis() + 300;
}

// ========================================
// Hauptschleife
// ========================================

void loop() {
  uint32_t now = millis();

  for (auto &p : baseState) {
    updatePixel(p);
  }

  for (auto &p : flowerState) {
    updatePixel(p);
  }

  if (now >= nextBaseSpawn) {
    spawnRandom(baseState, BASE_COUNT);
    nextBaseSpawn = now + random(180, 650);
  }

  if (now >= nextFlowerSpawn) {
    spawnRandom(flowerState, FLOWER_COUNT);
    nextFlowerSpawn = now + random(250, 900);
  }

  renderWithLimit();

  delay(20);
}
